    cursor[2] = 1;
    cursor[3] = 0x14;
    cursor[4] = 0x2400000000000001UL;
    cursor[5] = 0x61;
    cursor[6] = color & 0xFFFFFFFFUL;
    cursor[7] = debug_font_pif_header;
