/* ParseOcclGrid(x, y, z): walks the three-level occlusion grid at
   occlusion_grid, the same function as the core's ParseOcclGrid (src/game/render/draw.c).
   Each level is {u16 start, u16 count, u16 entry[count]}; the coordinate minus
   start must fall in [0, count). Retail's function is 0xD4 bytes: this stub's
   0x84 bytes, the occl_grid_lookup_tail piece (0x48) and the shared return
   (noop_callback_l, 8 bytes) are one C function (config/overlays/joined.tsv). */

/* Looks cell (X, Y, Z) up in the three-level occlusion grid at occlusion_grid: 0 when the coordinate falls
   outside a level or the cell is empty, else the address of the cell's 128-byte occlusion record. */
int OcclGrid_Lookup(int x, int y, int z) {
    char *grid = occlusion_grid;
    char *base = grid + *(int *)grid;
    unsigned short *l = (unsigned short *)(grid + 4);
    int cz, cy, cx;

    cz = z - l[0];
    if (cz < 0)
        return 0;
    if (cz >= l[1])
        return 0;
    if (l[cz + 2] == 0)
        return 0;
    l = (unsigned short *)(grid + l[cz + 2] * 4);
    cy = y - l[0];
    if (cy < 0)
        return 0;
    if (cy >= l[1])
        return 0;
    if (l[cy + 2] == 0)
        return 0;
    l = (unsigned short *)(grid + l[cy + 2] * 4);
    cx = x - l[0];
    if (cx < 0 || cx >= l[1])
        return 0;
    if (l[cx + 2] == 0xFFFF)
        return 0;
    return (int)(base + l[cx + 2] * 128);
}
